package com.mealflex.growth.service;
import com.mealflex.store.entity.StoreView; import com.mealflex.store.repository.StoreViewRepository; import com.mealflex.subscription.entity.SubscriptionStatus; import com.mealflex.subscription.repository.SubscriptionRepository; import com.mealflex.user.entity.User; import com.mealflex.user.repository.NotificationPreferenceRepository; import com.mealflex.user.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.Pageable; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class CustomerGrowthService { private final UserRepository users; private final SubscriptionRepository subscriptions; private final StoreViewRepository views; private final NotificationPreferenceRepository preferences;
 @Transactional public Map<String,Object> insight(Long userId){User user=users.findById(userId).orElseThrow();long subscriptionsCount=subscriptions.findByCustomerId(userId,Pageable.ofSize(1000)).getTotalElements();String segment=subscriptionsCount==0?"NEW":(subscriptions.findByCustomerIdAndStatus(userId,SubscriptionStatus.ACTIVE,Pageable.ofSize(1)).hasContent()?"ACTIVE":"PAST");List<Map<String,Object>> suggestions=views.findByUserIdOrderByViewedAtDesc(userId,Pageable.ofSize(6)).stream().map(StoreView::getStore).filter(s->s.getDeletedAt()==null).map(s->Map.<String,Object>of("storeId",s.getId(),"storeName",s.getName(),"reason","Daha önce görüntülediğiniz işletme")).toList();var pref=preferences.findByUserId(userId).orElse(null);if(user.getReferralCode()==null){user.setReferralCode("MF"+user.getId()+UUID.randomUUID().toString().substring(0,6).toUpperCase());users.save(user);}return Map.of("segment",segment,"referralCode",user.getReferralCode(),"marketingAllowed",pref!=null&&pref.isMarketingEnabled(),"suggestions",suggestions,"frequencyLimit","Pazarlama bildirimleri kullanıcı tercihiyle ve günde en fazla bir kez gönderilir.");}
}
